type PropertyValue = string | number | boolean | Date;
interface HasProperties { [name: string]: PropertyValue | undefined; }

class Order implements HasProperties {
  [name: string]: PropertyValue | undefined;
  static from(data: Record<string, unknown>): Order {   // validate once, at the boundary
    const order: HasProperties = new Order();
    for (const [key, value] of Object.entries(data)) order[key] = validate(key, value);
    return order as Order;
  }
  propertyNames(): string[] { return Object.keys(this); }  // discoverability
}

declare function validate(key: string, value: unknown): PropertyValue;
